INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21QDSIS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $27$ feet and a width of $16$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '432', ARRAY['432'], E'The area of a rectangle is $A = l \\times w = 27 \\times 16 = 432$ square feet.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM226F7DB', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'Given the system of equations $5x - 3y = -6$ and $2x + 9y = 69$, what is the value of $xy$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Multiplying the first equation by 3 gives $15x - 9y = -18$. Adding this to the second equation: $(15x - 9y) + (2x + 9y) = -18 + 69$, which simplifies to $17x = 51$, so $x = 3$. Substituting into the first equation: $5(3) - 3y = -6$, so $15 - 3y = -6$, giving $-3y = -21$ and $y = 7$. Therefore $xy = 3 \\times 7 = 21$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22AH9F9', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A delivery service charges $\\$17$ for the first package and $\\$6$ for each additional package. A customer can spend no more than $\\$71$ on deliveries. What is the maximum number of total packages the customer can have delivered?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'The cost for $m$ total packages is $17 + 6(m - 1) = 11 + 6m$. Setting up the inequality $11 + 6m \\leq 71$ gives $6m \\leq 60$, so $m \\leq 10$. Since $m$ must be a whole number, the maximum number of packages is 10.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM230JUP0', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'At how many points do the graphs of $y = x^2 - 3x + 1$ and $y = 2x - 3$ intersect?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting $x^2 - 3x + 1 = 2x - 3$ gives $x^2 - 5x + 4 = 0$, which factors as $(x - 1)(x - 4) = 0$. This has two distinct real solutions, so the graphs intersect at $2$ points. Choosing $0$ results from an error in rearranging the equation. Choosing $1$ may come from incorrectly concluding the discriminant is zero. Choosing $3$ reflects a misconception that a parabola and line can intersect in three places.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23BNB53', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'The expression $\\frac{5}{x + 3} + \\frac{2}{x - 1}$ can be written as $\\frac{ax + b}{(x + 3)(x - 1)}$, where $a$ and $b$ are constants. What is the value of $a + b$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$12$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining fractions over the common denominator: $\\frac{5(x - 1) + 2(x + 3)}{(x + 3)(x - 1)} = \\frac{5x - 5 + 2x + 6}{(x + 3)(x - 1)} = \\frac{7x + 1}{(x + 3)(x - 1)}$. So $a = 7$ and $b = 1$, giving $a + b = 8$. Choosing $-8$ results from sign errors in the cross-multiplication. Choosing $12$ comes from incorrectly computing $5 + 2 + 3 + 2 = 12$ without proper algebraic combination. Choosing $4$ results from only partially combining terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23Z42V0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a survey of 860 residents, $45\\%$ preferred option X. After 140 additional residents were surveyed, the overall percentage preferring option X changed to $42\\%$. How many of the 140 additional residents preferred option X?', NULL, $lyceon_json$[{"key":"A","text":"27"},{"key":"B","text":"33"},{"key":"C","text":"47"},{"key":"D","text":"59"}]$lyceon_json$::jsonb, 'B', NULL, E'From the original 860 residents, $0.45 \\times 860 = 387$ preferred option X. The total number of residents is $860 + 140 = 1000$. At $42\\%$ overall, $0.42 \\times 1000 = 420$ prefer option X. So the number from the additional group is $420 - 387 = 33$. The value 27 comes from computing $42\\%$ of only the 140 additional residents rather than using the overall count. The value 47 results from setting up the equation incorrectly, such as computing $\\frac{387 + x}{140} = 0.42$. The value 59 results from an arithmetic error in the subtraction step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VNAX1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What value of $x$ satisfies the equation $\\frac{2(3x + 7)}{5} = \\frac{4x - 1}{3}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47/2', ARRAY['47/2', '23.5'], E'Cross-multiply to eliminate fractions: $3 \\cdot 2(3x + 7) = 5(4x - 1)$. Distribute on the left: $6(3x + 7) = 18x + 42$. Distribute on the right: $20x - 5$. Set them equal: $18x + 42 = 20x - 5$. Subtract $18x$ from both sides: $42 = 2x - 5$. Add $5$: $47 = 2x$. Divide by $2$: $x = \\frac{47}{2}$. A common error is to cross-multiply incorrectly, forgetting to distribute the $2$ inside the parentheses on the left side, which leads to a different value of $x$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM252UMHC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2x^2 + 20x - 43$ can be rewritten in the form $h(x) = -2(x - a)^2 + b$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-43$"},{"key":"C","text":"$50$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square: $h(x) = -2(x^2 - 10x) - 43 = -2(x^2 - 10x + 25 - 25) - 43 = -2(x - 5)^2 + 50 - 43 = -2(x - 5)^2 + 7$. So $b = 7$. The value $-43$ comes from reading the original constant without completing the square (partial reasoning). The value $50$ comes from forgetting to subtract $43$ after distributing (sign error). The value $-7$ comes from subtracting $50$ instead of adding it (arithmetic slip).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254VK3O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In right triangle $DEF$ with the right angle at $E$, $DE = 24$ and $EF = 7$. What is the length of $DF$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'Using the Pythagorean theorem with legs $DE = 24$ and $EF = 7$: $DF^2 = 24^2 + 7^2 = 576 + 49 = 625$, so $DF = 25$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM266EN1B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A jar contains 8 red marbles, 5 blue marbles, and 7 green marbles. Two marbles are drawn at random without replacement. Given that the first marble drawn is green, what is the probability that the second marble drawn is also green?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{20}$"},{"key":"B","text":"$\\frac{6}{19}$"},{"key":"C","text":"$\\frac{7}{19}$"},{"key":"D","text":"$\\frac{6}{20}$"}]$lyceon_json$::jsonb, 'B', NULL, E'There are $8 + 5 + 7 = 20$ marbles total. Given the first marble drawn is green, there are now 6 green marbles remaining out of 19 total marbles. So the probability is $\\frac{6}{19}$. The value $\\frac{7}{20}$ uses the original count of green marbles over the original total, ignoring the without-replacement condition. The value $\\frac{7}{19}$ correctly reduces the total to 19 but fails to reduce the green count after one green is removed. The value $\\frac{6}{20}$ reduces the green count but not the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28E52GF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of 500 voters in a city found that $58\\%$ support a proposed policy, with a margin of error of $3.5$ percentage points at $95\\%$ confidence. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $54.5\\%$ and $61.5\\%$ of all voters in the city are likely to support the policy."},{"key":"B","text":"Exactly $58\\%$ of all voters in the city support the policy."},{"key":"C","text":"Between $54.5\\%$ and $61.5\\%$ of the 500 sampled voters support the policy."},{"key":"D","text":"If the survey were repeated, $95\\%$ of respondents would say they support the policy."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error means the plausible range for the true population proportion is $58\\% \\pm 3.5\\%$, or from $54.5\\%$ to $61.5\\%$, at $95\\%$ confidence. This interval applies to the entire population of voters, not just the sample. Stating exactly $58\\%$ ignores sampling variability. Applying the interval to the sample confuses the sample statistic with the population parameter. Claiming $95\\%$ of respondents would support the policy misinterprets the confidence level.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28NHVT6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'When the expression $\\frac{6x^3 + 15x^2}{3x}$ is simplified, the result can be written as $2x^2 + cx$ for a constant $c$. What is the value of $c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Dividing each term by $3x$: $\\frac{6x^3}{3x} + \\frac{15x^2}{3x} = 2x^2 + 5x$. Comparing with $2x^2 + cx$ gives $c = 5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2922JS1', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $6x + 17 = 71$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Subtract $17$ from both sides: $6x = 54$. Divide both sides by $6$: $x = 9$. A student who forgets to subtract $17$ and divides $71$ by $6$ would get approximately $11.83$, which is incorrect. A student who subtracts in the wrong order, computing $17 - 71 = -54$, would get $x = -9$, a sign error.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29MOGTP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a circumference of $34\\pi$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$17$"},{"key":"C","text":"$68$"},{"key":"D","text":"$\\frac{17\\pi}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference formula is $C = 2\\pi r$. Setting $2\\pi r = 34\\pi$ and dividing both sides by $2\\pi$ gives $r = 17$. The value $34$ confuses the radius with the diameter, since the diameter equals $34$. The value $68$ doubles the diameter instead of halving it. The value $\\frac{17\\pi}{2}$ results from dividing $34\\pi$ by $2$ without canceling the $\\pi$ factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ABL0FI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The equation $2x^2 + 7x - 15 = 0$ has two solutions. What is their sum?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{7}{2}$"},{"key":"B","text":"$\\frac{7}{2}$"},{"key":"C","text":"$-\\frac{15}{2}$"},{"key":"D","text":"$\\frac{15}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By Vieta''s formulas, for $ax^2 + bx + c = 0$, the sum of the roots is $-b/a$. Here $a = 2$ and $b = 7$, so the sum is $-7/2$. Choosing $7/2$ neglects the negative sign in Vieta''s formula. Choosing $-15/2$ confuses the sum formula with the product formula $c/a$. Choosing $15/2$ makes both the sign and formula errors simultaneously.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AWPJ6K', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following points $(x, y)$ is a solution to the system of inequalities $y > 3x - 5$ and $y \\leq -2x + 11$?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 1)$"},{"key":"B","text":"$(2, 3)$"},{"key":"C","text":"$(3, 6)$"},{"key":"D","text":"$(0, -6)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Testing $(2, 3)$: the first inequality gives $3 > 3(2) - 5 = 1$, which is true, and the second gives $3 \\leq -2(2) + 11 = 7$, which is true, so $(2, 3)$ satisfies both. Testing $(4, 1)$: $1 > 3(4) - 5 = 7$ is false, so it fails the first inequality. Testing $(3, 6)$: while $6 > 3(3) - 5 = 4$ is true, $6 \\leq -2(3) + 11 = 5$ is false, so it fails the second inequality. Testing $(0, -6)$: $-6 > 3(0) - 5 = -5$ is false, so it fails the first inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BRFRUJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $4(x + 3) = 52$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$13$"},{"key":"C","text":"$16$"},{"key":"D","text":"$-10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Divide both sides by $4$ to get $x + 3 = 13$, then subtract $3$ to find $x = 10$. The value $13$ results from dividing $52$ by $4$ but forgetting to subtract $3$, stopping one step early. The value $16$ comes from incorrectly adding $12$ to $52$ (using $52 + 12 = 64$, then $64 / 4 = 16$) instead of dividing first. The value $-10$ reverses the sign of the correct answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BRUW0Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A bookstore originally prices a journal at $\\$42$. During a sale, the price is reduced by $35\\%$. What is the sale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27.3', ARRAY['27.3'], E'The discount amount is $42 \\times 0.35 = 14.70$. The sale price is $42 - 14.70 = 27.30$ dollars. Equivalently, the sale price is $42 \\times 0.65 = 27.30$.', NULL, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C6YOQL', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = -3x + 29$. What is the value of $f(8)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$53$"},{"key":"D","text":"$-24$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 8$: $f(8) = -3(8) + 29 = -24 + 29 = 5$. The value $-5$ reverses the sign of the correct result. The value $53$ comes from computing $3(8) + 29 = 24 + 29 = 53$, ignoring the negative coefficient. The value $-24$ results from computing $-3(8) = -24$ but stopping there without adding $29$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CNZUPB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A car rental company charges a one-time fee plus a fixed daily rate. The total cost $C$, in dollars, of renting a car for $d$ days is modeled by the function $C(d) = 43d + 29$. Which of the following is the best interpretation of the number $43$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The total cost, in dollars, of renting the car"},{"key":"B","text":"The one-time fee, in dollars, charged by the company"},{"key":"C","text":"The increase in total cost, in dollars, for each additional day the car is rented"},{"key":"D","text":"The number of days the car is rented"}]$lyceon_json$::jsonb, 'C', NULL, E'In the function $C(d) = 43d + 29$, the coefficient $43$ multiplies the variable $d$, so it represents the rate of change: the cost increases by $\\$43$ for each additional day. The total cost is $C(d)$ itself, not a single coefficient. The one-time fee is represented by $29$, the constant term, not the coefficient of $d$. The number of days is represented by the input variable $d$, not by a constant in the formula.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CW4TJ4', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line in the $xy$-plane has the equation $3x + 7y = 42$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$14$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$\\frac{3}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting: $7y = 42$, so $y = 6$. The value $14$ results from setting $y = 0$ instead and solving for $x$ ($3x = 42$, $x = 14$), which gives the $x$-intercept rather than the $y$-intercept. The value $-6$ incorrectly reverses the sign of the correct answer. The value $\\frac{3}{7}$ confuses the slope of the line (in slope-intercept form, $y = -\\frac{3}{7}x + 6$, the slope is $-\\frac{3}{7}$) with the intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CYAEQV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data and finds a line of best fit given by $y = 3.7x + 11.2$. What is the predicted value of $y$ when $x = 9$, and what does the slope represent in this context if $x$ is the number of weeks and $y$ is the total output in units?', NULL, $lyceon_json$[{"key":"A","text":"$44.5$; the output increases by $11.2$ units per week"},{"key":"B","text":"$44.5$; the output increases by $3.7$ units per week"},{"key":"C","text":"$44.5$; the initial output is $3.7$ units"},{"key":"D","text":"$44.3$; the output increases by $3.7$ units per week"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 9$: $y = 3.7(9) + 11.2 = 33.3 + 11.2 = 44.5$. In the equation $y = 3.7x + 11.2$, the slope $3.7$ represents the predicted increase in output per week, which is $3.7$ units per week. The option stating the output increases by $11.2$ units per week confuses the slope with the $y$-intercept. The option stating the initial output is $3.7$ units reverses the roles of slope and intercept. The option giving $44.3$ makes an arithmetic error in computing $3.7 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DIY6L2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $\\frac{(2x + 3)^2 - (2x - 3)^2}{x}$ simplifies to a constant for all $x \\neq 0$, what is that constant?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '24', ARRAY['24'], E'Expanding: $(2x + 3)^2 = 4x^2 + 12x + 9$ and $(2x - 3)^2 = 4x^2 - 12x + 9$. Their difference is $(4x^2 + 12x + 9) - (4x^2 - 12x + 9) = 24x$. Dividing by $x$ gives $24$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ECBLCD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, side $AB = 11$, side $BC = 17$, and side $AC = 23$. A line segment $BD$ is drawn from vertex $B$ to a point $D$ on side $AC$ such that $BD$ bisects angle $B$. By the angle bisector theorem, what is the length of $AD$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{253}{17}$"},{"key":"B","text":"$\\frac{253}{28}$"},{"key":"C","text":"$\\frac{391}{28}$"},{"key":"D","text":"$\\frac{11}{28}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the angle bisector theorem, $\\frac{AD}{DC} = \\frac{AB}{BC} = \\frac{11}{17}$. Since $AD + DC = AC = 23$, let $AD = 11k$ and $DC = 17k$. Then $11k + 17k = 23$, so $28k = 23$ and $k = \\frac{23}{28}$. Therefore $AD = 11 \\cdot \\frac{23}{28} = \\frac{253}{28}$. The value $\\frac{253}{17}$ results from dividing $11 \\cdot 23$ by $17$ alone, setting up the proportion incorrectly. The value $\\frac{391}{28}$ equals $\\frac{17 \\cdot 23}{28}$, which is $DC$ rather than $AD$, answering for the wrong segment. The value $\\frac{11}{28}$ uses $k$ itself rather than multiplying by $11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EO18KN', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A farmer plants Crop X and Crop Y on a total of at most 50 acres. Crop X requires 3 pounds of fertilizer per acre, and Crop Y requires 5 pounds per acre. The farmer has 210 pounds of fertilizer available and wants to plant at least 15 acres of Crop X. What is the maximum number of acres of Crop Y the farmer can plant?', NULL, $lyceon_json$[{"key":"A","text":"33"},{"key":"B","text":"35"},{"key":"C","text":"42"},{"key":"D","text":"31"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $x$ be acres of Crop X and $y$ be acres of Crop Y. The constraints are $x + y \\leq 50$, $3x + 5y \\leq 210$, and $x \\geq 15$. To maximize $y$, set $x = 15$. The acreage constraint gives $y \\leq 35$. The fertilizer constraint gives $3(15) + 5y \\leq 210$, so $45 + 5y \\leq 210$, giving $y \\leq 33$. The binding constraint is fertilizer, so the maximum is 33 acres. The answer 35 comes from only checking the acreage constraint and ignoring the fertilizer limit. The answer 42 comes from dividing 210 by 5 without accounting for any Crop X acreage. The answer 31 results from an arithmetic error such as computing $3 \\times 15 = 55$ instead of $45$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F5KVST', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Line $p$ passes through the points $(2, -3)$ and $(8, 15)$. Which of the following is the equation of line $p$?', NULL, $lyceon_json$[{"key":"A","text":"$y = 3x - 9$"},{"key":"B","text":"$y = 3x + 9$"},{"key":"C","text":"$y = \\frac{1}{3}x - 9$"},{"key":"D","text":"$y = -3x + 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{15 - (-3)}{8 - 2} = \\frac{18}{6} = 3$. Using point-slope form with $(2, -3)$: $y - (-3) = 3(x - 2)$, which simplifies to $y = 3x - 9$. Verification: at $x = 8$, $y = 24 - 9 = 15$. The equation $y = 3x + 9$ has the correct slope but the wrong sign on the intercept, yielding $y = 15$ at $x = 2$, not $-3$. The equation $y = \\frac{1}{3}x - 9$ uses the reciprocal of the slope rather than the slope itself, reflecting a misunderstanding of the slope formula. The equation $y = -3x + 9$ negates the slope, giving a line that decreases rather than increases.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FB8IYV', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A plumber charges a flat fee of $\\$38$ for a service call plus $\\$19$ per hour of labor. If a customer''s total bill was $\\$171$, for how many hours did the plumber work?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$11$"},{"key":"D","text":"$133$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set up the equation $19h + 38 = 171$. Subtract $38$: $19h = 133$. Divide by $19$: $h = 7$. The value $9$ comes from dividing the total $171$ by $19$ without first subtracting the flat fee, stopping short of the full solution. The value $11$ results from adding $38$ to $171$ instead of subtracting it ($209 / 19 = 11$), an arithmetic slip in the direction of the operation. The value $133$ comes from computing $171 - 38 = 133$ but reporting this intermediate result instead of dividing by $19$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FNPHRL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A research team wants to determine whether a new fertilizer causes increased crop yield. They assign 130 plots randomly to receive either the new fertilizer or no fertilizer. After one growing season, the plots receiving the new fertilizer had a significantly higher average yield. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer is likely to cause increased crop yield because the study used random assignment."},{"key":"B","text":"The new fertilizer is associated with increased crop yield, but a causal conclusion cannot be drawn because the study lacked a control group."},{"key":"C","text":"The new fertilizer causes increased crop yield in all soil types because the sample size was large."},{"key":"D","text":"No conclusion can be drawn because the study did not use a random sample of plots from all farms."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the 130 plots were randomly assigned to treatment and control groups, the study is a randomized experiment, which supports a causal conclusion. The claim that there was no control group is incorrect — the plots receiving no fertilizer serve as the control. The claim that the fertilizer works in all soil types overgeneralizes beyond the study''s scope. The claim that no conclusion is possible because plots were not randomly sampled confuses random assignment (needed for causation) with random sampling (needed for generalizability); causal inference is still valid within the study population.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GCMV7X', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $\\sqrt{3x + 7} = 8$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19', ARRAY['19'], E'Squaring both sides: $3x + 7 = 64$, so $3x = 57$, giving $x = 19$. Checking: $\\sqrt{3(19) + 7} = \\sqrt{64} = 8$, which confirms the answer.', NULL, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOIJSY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $\\frac{5x - 3}{2} = 16$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{29}{5}$"},{"key":"C","text":"$\\frac{19}{5}$"},{"key":"D","text":"$\\frac{35}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by $2$: $5x - 3 = 32$. Add $3$: $5x = 35$. Divide by $5$: $x = 7$. The value $\\frac{29}{5}$ results from subtracting $3$ from $32$ instead of adding it (sign error: $5x = 29$). The value $\\frac{19}{5}$ comes from skipping the multiplication by $2$ and solving $5x - 3 = 16$ directly, giving $5x = 19$. The value $\\frac{35}{2}$ arises from correctly finding $5x = 35$ but then dividing by $2$ instead of $5$, confusing the denominator with the coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IHKOHY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'If $5x - 3y = 22$ and $2x + 3y = 13$, what is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"4"},{"key":"C","text":"6"},{"key":"D","text":"1"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(5x - 3y) + (2x + 3y) = 22 + 13$, giving $7x = 35$, so $x = 5$. Substituting back into the second equation: $2(5) + 3y = 13$, so $3y = 3$ and $y = 1$. Therefore $x + y = 5 + 1 = 6$. The value 5 is $x$ alone, not $x + y$. The value 4 results from a sign error when solving for $y$, such as getting $y = -1$. The value 1 is $y$ alone, not $x + y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7SYZ0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following describes all values of $x$ that satisfy the inequality $7x + 11 \\leq 67$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 56$"},{"key":"B","text":"$x \\geq 8$"},{"key":"C","text":"$x \\leq 8$"},{"key":"D","text":"$x \\leq \\frac{67}{7}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Subtracting 11 from both sides gives $7x \\leq 56$, and dividing both sides by 7 gives $x \\leq 8$. The answer $x \\leq 56$ results from subtracting 11 but forgetting to divide by 7. The answer $x \\geq 8$ incorrectly reverses the inequality direction when dividing by a positive number. The answer $x \\leq \\frac{67}{7}$ results from dividing 67 by 7 without first subtracting 11.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J9MZRZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3(x + 2)^2 - 5$, and the function $g$ is defined by $g(x) = f(x - 7) + 4$. What is the $y$-coordinate of the vertex of $y = g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$4$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The vertex of $f(x) = 3(x + 2)^2 - 5$ is at $(-2, -5)$. The transformation $g(x) = f(x - 7) + 4$ shifts $f$ right $7$ units and up $4$ units. The horizontal shift changes the $x$-coordinate of the vertex but does not affect the $y$-coordinate. The vertical shift adds $4$ to the $y$-coordinate: $-5 + 4 = -1$. So the $y$-coordinate of the vertex of $g$ is $-1$. The value $-9$ comes from subtracting $4$ instead of adding it (sign error). The value $4$ comes from considering only the vertical shift without the original vertex $y$-value (partial reasoning). The value $-5$ comes from ignoring the vertical shift entirely (concept gap).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JPRQTK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = -\\frac{1}{2}(x - 3)(x - 11)$ models the height, in feet, of a ball $x$ seconds after being thrown, where $0 \\leq x \\leq 11$. What is the maximum height, in feet, the ball reaches?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{49}{8}$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'The zeros of $f$ are at $x = 3$ and $x = 11$. The axis of symmetry is $x = \\frac{3 + 11}{2} = 7$. The maximum height is $f(7) = -\\frac{1}{2}(7 - 3)(7 - 11) = -\\frac{1}{2}(4)(-4) = -\\frac{1}{2}(-16) = 8$ feet. The value $7$ confuses the $x$-coordinate of the vertex with the maximum height (arithmetic slip, substituting incorrectly). The value $\\frac{49}{8}$ results from an incorrect expansion of the function before evaluating (equation setup error). The value $16$ comes from computing $(4)(4) = 16$ but omitting the factor of $-\\frac{1}{2}$ (concept gap).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KSZ5WH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $g$ is defined by $g(x) = \\frac{3x - 11}{4}$. For what value of $x$ does $g(x) = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Set $g(x) = 7$: $\\frac{3x - 11}{4} = 7$. Multiply both sides by $4$: $3x - 11 = 28$. Add $11$ to both sides: $3x = 39$. Divide by $3$: $x = 13$. A common error is forgetting to multiply by $4$, solving $3x - 11 = 7$ instead, which gives $x = 6$. Another error is subtracting $11$ instead of adding it after multiplying, yielding $3x = 17$ and $x = \\frac{17}{3}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L4J302', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A machine fills 37 bottles in 4 minutes. At this rate, how many bottles does the machine fill in 20 minutes?', NULL, $lyceon_json$[{"key":"A","text":"148"},{"key":"B","text":"185"},{"key":"C","text":"157"},{"key":"D","text":"740"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37}{4}$ bottles per minute, which equals $9.25$ bottles per minute. In 20 minutes the machine fills $9.25 \\times 20 = 185$ bottles. The value 148 results from incorrectly multiplying $37 \\times 4$ instead of dividing. The value 157 comes from an incorrect setup such as adding 120 to 37. The value 740 results from multiplying $37 \\times 20$ without accounting for the 4-minute interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LKUZ28', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 6x + k$ and $y = 2x - 9$ has exactly one solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x^2 - 6x + k = 2x - 9$ gives $x^2 - 8x + (k + 9) = 0$. For exactly one solution, the discriminant must equal zero: $64 - 4(k + 9) = 0$, so $64 - 4k - 36 = 0$, giving $28 = 4k$ and $k = 7$. Choosing $-7$ reflects a sign error when isolating $k$. Choosing $5$ results from an arithmetic slip in expanding $4(k + 9)$. Choosing $-5$ comes from incorrectly setting up the combined equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MIYKNZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'In the $xy$-plane, line $m$ is perpendicular to the line $4x - 6y = 9$ and passes through the point $(-5, 1)$. What is the $y$-intercept of line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{13}{2}$"},{"key":"B","text":"$\\frac{13}{2}$"},{"key":"C","text":"$-\\frac{17}{2}$"},{"key":"D","text":"$\\frac{13}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite $4x - 6y = 9$ in slope-intercept form: $y = \\frac{2}{3}x - \\frac{3}{2}$, so the slope is $\\frac{2}{3}$. The perpendicular slope is $-\\frac{3}{2}$. Using point-slope form with $(-5, 1)$: $y - 1 = -\\frac{3}{2}(x + 5)$, which gives $y = -\\frac{3}{2}x - \\frac{15}{2} + 1 = -\\frac{3}{2}x - \\frac{13}{2}$. The $y$-intercept is $-\\frac{13}{2}$. The value $\\frac{13}{2}$ drops the negative sign from the intercept. The value $-\\frac{17}{2}$ arises from subtracting $1$ instead of adding it when isolating $y$ ($-\\frac{15}{2} - 1 = -\\frac{17}{2}$). The value $\\frac{13}{3}$ results from using the original slope $\\frac{2}{3}$ instead of the perpendicular slope, yielding $y = \\frac{2}{3}x + \\frac{13}{3}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MNPRHE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $47°$ and angle $Q$ measures $68°$. An exterior angle is formed at vertex $R$ by extending side $QR$ beyond $R$. What is the measure, in degrees, of this exterior angle?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$115$"},{"key":"C","text":"$112$"},{"key":"D","text":"$133$"}]$lyceon_json$::jsonb, 'B', NULL, E'The interior angle at $R$ is $180 - 47 - 68 = 65°$. The exterior angle at $R$ is supplementary to the interior angle: $180 - 65 = 115°$. Equivalently, by the exterior angle theorem, it equals the sum of the two remote interior angles: $47 + 68 = 115°$. The value $65$ is the interior angle at $R$, not the exterior angle. The value $112$ results from an arithmetic error such as computing $47 + 65$. The value $133$ results from adding $68 + 65$, misidentifying which angles to sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NEUNMM', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{9x^2 - 16}{3x + 4}$ for $x \\neq -\\frac{4}{3}$?', NULL, $lyceon_json$[{"key":"A","text":"$3x + 4$"},{"key":"B","text":"$3x - 4$"},{"key":"C","text":"$9x - 4$"},{"key":"D","text":"$3x - 16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $9x^2 - 16$ is a difference of squares: $(3x)^2 - 4^2 = (3x + 4)(3x - 4)$. Dividing by $3x + 4$ yields $3x - 4$. Choosing $3x + 4$ reflects a sign error in the factorization. Choosing $9x - 4$ misapplies the difference-of-squares pattern. Choosing $3x - 16$ results from incomplete simplification.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NY0D3C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A right circular cylinder has a radius of $3$ and a height of $11$. A second right circular cylinder has a radius of $9$ and a height of $11$. The volume of the larger cylinder is how many times the volume of the smaller cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$27$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Volume of a cylinder is $V = \\pi r^2 h$. Since both cylinders share the same height, the ratio of volumes is $\\frac{\\pi(9)^2(11)}{\\pi(3)^2(11)} = \\frac{81}{9} = 9$. The value $3$ is the ratio of the radii, not accounting for the fact that volume depends on $r^2$. The value $27$ cubes the ratio of radii, confusing the scaling with a three-dimensional ratio applied to the radius alone. The value $6$ results from doubling the radius ratio, an arithmetic error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NYRAFL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The quadratic function $f(x) = 4x^2 - 24x + 41$ has a minimum value. What is this minimum value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Completing the square: $f(x) = 4(x^2 - 6x) + 41 = 4(x^2 - 6x + 9 - 9) + 41 = 4(x - 3)^2 - 36 + 41 = 4(x - 3)^2 + 5$. The minimum value occurs when $(x - 3)^2 = 0$, giving $f(3) = 5$. Alternatively, the vertex $x$-coordinate is $x = \\frac{-(-24)}{2(4)} = 3$, and $f(3) = 4(9) - 24(3) + 41 = 36 - 72 + 41 = 5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OSOAF5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'If $x^2 - 13x + 42 = 0$, which of the following is a solution for $x$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring: $x^2 - 13x + 42 = (x - 6)(x - 7) = 0$, giving $x = 6$ or $x = 7$. Among the choices, $6$ is a solution. Choosing $3$ results from an arithmetic error in finding factor pairs of $42$. Choosing $-6$ or $-7$ reflects sign errors when extracting roots from the factored form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZY7PF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle in the $xy$-plane has equation $(x - 5)^2 + (y + 7)^2 = 169$. A point on this circle has $x$-coordinate $17$. If this point has the greater $y$-coordinate of the two possible points with $x$-coordinate $17$, what is its $y$-coordinate?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'Substituting $x = 17$: $(17 - 5)^2 + (y + 7)^2 = 169$, so $144 + (y + 7)^2 = 169$, giving $(y + 7)^2 = 25$. Thus $y + 7 = \\pm 5$, yielding $y = -2$ or $y = -12$. Since $-2 > -12$, the greater $y$-coordinate is $-2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PQ6U2K', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $h$ satisfies $h(3) = 19$ and $h(11) = -5$. What is the value of $h(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$19$"},{"key":"C","text":"$28$"},{"key":"D","text":"$-28$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $\\frac{-5 - 19}{11 - 3} = \\frac{-24}{8} = -3$. Using $h(3) = 19$: $19 = -3(3) + b$, so $b = 19 + 9 = 28$. Therefore $h(0) = 28$. The value $10$ results from computing the slope as $+3$ instead of $-3$ (reversing the sign of the numerator), giving $19 = 3(3) + b$, $b = 10$. The value $19$ comes from assuming $h(0) = h(3)$ without computing the actual intercept. The value $-28$ arises from finding $b = 28$ but then negating it when reporting the answer.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PXNXSJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $134°$. If angle $P$ measures $58°$, what is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$76$"},{"key":"B","text":"$46$"},{"key":"C","text":"$134$"},{"key":"D","text":"$122$"}]$lyceon_json$::jsonb, 'A', NULL, E'The exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $134 = 58 + Q$, so $Q = 134 - 58 = 76$. The value $46$ results from computing $180 - 134 = 46$, confusing the exterior angle with a supplementary-angle calculation applied to the wrong pair. The value $134$ mistakes the exterior angle itself for the interior angle at $Q$. The value $122$ comes from computing $180 - 58 = 122$, which is the supplement of angle $P$, not angle $Q$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RTI5HY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A system of two linear equations in two variables has no solution. One equation in the system is $8x - 6y = 14$. Which of the following could be the other equation in the system?', NULL, $lyceon_json$[{"key":"A","text":"$4x - 3y = 11$"},{"key":"B","text":"$4x - 3y = 7$"},{"key":"C","text":"$8x + 6y = 14$"},{"key":"D","text":"$6x - 8y = 14$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: same slope but different intercepts. Rewriting $8x - 6y = 14$ by dividing by 2 gives $4x - 3y = 7$. A parallel line must have the form $4x - 3y = k$ where $k \\neq 7$. The equation $4x - 3y = 11$ satisfies this, since $11 \\neq 7$. The equation $4x - 3y = 7$ is equivalent to the original equation, which gives infinitely many solutions rather than no solution. The equation $8x + 6y = 14$ has a different slope because the sign on $y$ changed. The equation $6x - 8y = 14$ has a different slope because the coefficients on $x$ and $y$ were swapped.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T6DP27', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$, angle $F = 90°$, side $DF = 7$, and side $EF = 24$. What is the value of $\\sin(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{25}$"},{"key":"B","text":"$\\frac{24}{25}$"},{"key":"C","text":"$\\frac{7}{24}$"},{"key":"D","text":"$\\frac{24}{7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find the hypotenuse $DE$: $DE = \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. Since $\\sin(D) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{EF}{DE} = \\frac{24}{25}$. The value $\\frac{7}{25}$ is $\\cos(D)$, confusing sine with cosine. The value $\\frac{7}{24}$ uses the two legs as a ratio without computing the hypotenuse, which would be $\\tan(E)$. The value $\\frac{24}{7}$ is $\\tan(D)$, confusing tangent with sine.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T9ZH44', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist travels 23 miles in 1 hour and 15 minutes. A second cyclist travels 31 miles in 1 hour and 40 minutes. What is the positive difference, in miles per hour, between the two cyclists'' average speeds?', NULL, $lyceon_json$[{"key":"A","text":"$0.2$"},{"key":"B","text":"$0.8$"},{"key":"C","text":"$3.0$"},{"key":"D","text":"$8.0$"}]$lyceon_json$::jsonb, 'A', NULL, E'The first cyclist''s speed is $\\frac{23}{1.25} = 18.4$ mph. The second cyclist''s speed is $\\frac{31}{\\frac{5}{3}} = \\frac{31 \\times 3}{5} = 18.6$ mph. The positive difference is $18.6 - 18.4 = 0.2$ mph. The value $0.8$ results from an arithmetic slip in computing one of the divisions. The value $3.0$ comes from subtracting miles ($31 - 23 = 8$) and then incorrectly dividing by the time difference. The value $8.0$ results from simply subtracting the distances without converting to rates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U0FRHL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The equation $5x - 4y = 60$ represents a line in the $xy$-plane. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'The $x$-intercept occurs where $y = 0$. Substituting $y = 0$ into the equation: $5x - 0 = 60$, so $5x = 60$ and $x = 12$. A common error is to set $x = 0$ instead, which gives the $y$-intercept ($-4y = 60$, $y = -15$) rather than the $x$-intercept.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U0XQ4U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains 9 values: 11, 14, 14, 17, 19, 22, 22, 22, 31. What is the interquartile range of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The median (5th value) is 19. The lower half is {11, 14, 14, 17}, so $Q_1 = \\frac{14 + 14}{2} = 14$. The upper half is {22, 22, 22, 31}, so $Q_3 = \\frac{22 + 22}{2} = 22$. The interquartile range is $Q_3 - Q_1 = 22 - 14 = 8$.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U5DIM9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'Given the system of equations $2x + y = 31$ and $y = x - 2$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"9"},{"key":"B","text":"33"},{"key":"C","text":"11"},{"key":"D","text":"13"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $y = x - 2$ into the first equation gives $2x + (x - 2) = 31$, so $3x - 2 = 31$, which gives $3x = 33$ and $x = 11$. The value 9 is $y$, not $x$, which would answer the wrong variable. The value 33 comes from computing $3x = 33$ but forgetting to divide by 3. The value 13 results from an arithmetic error when combining terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2URIUVQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = 5 \\cdot 2^x$. What is the value of $g(3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Substituting $x = 3$ into $g(x) = 5 \\cdot 2^x$ gives $g(3) = 5 \\cdot 2^3 = 5 \\cdot 8 = 40$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V8FXUH', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{x^2 + 11x + 28}{x + 4} - \\frac{x^2 - 9}{x - 3}$ can be written as a single integer for all valid values of $x$, what is that integer?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor $x^2 + 11x + 28 = (x + 4)(x + 7)$, so $\\frac{(x + 4)(x + 7)}{x + 4} = x + 7$. Factor $x^2 - 9 = (x - 3)(x + 3)$, so $\\frac{(x - 3)(x + 3)}{x - 3} = x + 3$. The difference is $(x + 7) - (x + 3) = 4$. Choosing $1$ comes from an error in the constant terms during subtraction. Choosing $-4$ reflects reversing the subtraction order. Choosing $7$ comes from only simplifying the first fraction and stopping.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W5PS70', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $5(3x - 4) + 2x$?', NULL, $lyceon_json$[{"key":"A","text":"$17x - 20$"},{"key":"B","text":"$17x - 4$"},{"key":"C","text":"$15x - 20$"},{"key":"D","text":"$17x + 20$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $5(3x - 4) + 2x = 15x - 20 + 2x = 17x - 20$. The expression $17x - 4$ results from failing to distribute the $5$ to $-4$. The expression $15x - 20$ omits combining $15x + 2x$. The expression $17x + 20$ incorrectly treats $-20$ as positive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBHKDC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of $x^2 = 81$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$41$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'A', NULL, E'Taking the square root of both sides gives $x = \\pm 9$. The question asks for the positive solution, so $x = 9$. Choosing $-9$ ignores the requirement for the positive solution. Choosing $41$ confuses dividing $81$ by $2$ with taking a square root. Choosing $18$ mistakenly doubles $9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XCNRLB', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'grid_in', E'If $5(x + 9) - 2x = 3x + k$ for all values of $x$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '45', ARRAY['45'], E'Expanding the left side: $5x + 45 - 2x = 3x + 45$. Since the equation must hold for all $x$, comparing $3x + 45 = 3x + k$ gives $k = 45$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XHHT0M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $\\frac{3}{x - 2} + \\frac{1}{x + 4} = \\frac{22}{(x - 2)(x + 4)}$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The denominator on the right factors as $(x - 2)(x + 4)$. Multiplying both sides by $(x - 2)(x + 4)$ gives $3(x + 4) + 1(x - 2) = 22$. Expanding: $3x + 12 + x - 2 = 22$, so $4x + 10 = 22$, giving $4x = 12$ and $x = 3$. Since $x = 3$ does not equal $2$ or $-4$, it is a valid solution. Checking: $\\frac{3}{1} + \\frac{1}{7} = \\frac{21}{7} + \\frac{1}{7} = \\frac{22}{7}$, and $\\frac{22}{(1)(7)} = \\frac{22}{7}$, confirming the answer.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YHKIXI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 - 7x + 11$. What is the value of $f(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$37$"},{"key":"C","text":"$21$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = -2$ into $f(x) = 3x^2 - 7x + 11$ gives $f(-2) = 3(-2)^2 - 7(-2) + 11 = 3(4) + 14 + 11 = 12 + 14 + 11 = 37$. The value $9$ results from incorrectly treating $(-2)^2$ as $-4$ (sign error on the squared term). The value $21$ results from computing $-7(-2)$ as $-14$ instead of $+14$ (arithmetic slip). The value $1$ results from ignoring the constant term (concept gap).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7US4S', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $p$ is defined by $p(x) = -x^3 + 4x^2 - 9$. As $x$ increases without bound, which of the following best describes the end behavior of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$p(x)$ increases without bound"},{"key":"B","text":"$p(x)$ decreases without bound"},{"key":"C","text":"$p(x)$ approaches $0$"},{"key":"D","text":"$p(x)$ approaches $-9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The leading term of $p(x) = -x^3 + 4x^2 - 9$ is $-x^3$. Since the leading coefficient is negative and the degree is odd, as $x$ increases without bound, $p(x)$ decreases without bound. The claim that $p(x)$ increases without bound ignores the negative leading coefficient (sign error). The claim that $p(x)$ approaches $0$ confuses polynomial end behavior with rational function behavior (concept gap). The claim that $p(x)$ approaches $-9$ mistakes the constant term for a horizontal asymptote (partial reasoning).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20PG1TM', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report on architectural preservation and wants to emphasize the economic benefit of restoring historic buildings. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on the Millhaven Textile Mill restoration:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22H5E3R', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Atacama Large Millimeter Array, a collection of sixty-six radio telescopes situated on a plateau in northern Chile, ______ astronomers to observe celestial phenomena that are invisible to optical instruments. Since becoming fully operational in 2013, the array has contributed to numerous discoveries, including the first direct image of a black hole.', $lyceon_json$[{"key":"A","text":"allow"},{"key":"B","text":"are allowing"},{"key":"C","text":"have allowed"},{"key":"D","text":"allows"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject of the verb is "The Atacama Large Millimeter Array," which is a singular noun (the phrase "a collection of sixty-six radio telescopes" is an appositive that describes it but does not change its number). A singular subject requires the singular verb form "allows." The bare plural form "allow" does not agree with the singular subject. The plural progressive "are allowing" incorrectly treats the subject as plural. The plural perfect "have allowed" also fails to agree with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22Y8MS7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Emeka Okafor has argued that the Benin Kingdom''s bronze-casting guilds operated under strict hereditary apprenticeship systems that limited artistic innovation. Recent metallurgical analyses of 146 plaques from the 16th and 17th centuries, however, reveal significant variation in alloy compositions and casting techniques across workshops. ______ the variation does not necessarily indicate creative freedom: some scholars contend that fluctuations in the tin supply from trans-Saharan trade routes forced artisans to adapt their methods regardless of guild regulations.', $lyceon_json$[{"key":"A","text":"That said,"},{"key":"B","text":"By extension,"},{"key":"C","text":"In addition to this evidence,"},{"key":"D","text":"Granted, this challenges Okafor's thesis, but"}]$lyceon_json$::jsonb, 'D', NULL, E'The passage moves through three logical stages: Okafor''s thesis of limited innovation, evidence that seems to undermine it (alloy variation), and then a reinterpretation that explains the variation without confirming creative freedom. The blank must both acknowledge that the metallurgical evidence challenges Okafor while simultaneously pivoting to the counterargument. "Granted, this challenges Okafor''s thesis, but" accomplishes both moves in one transition. "That said," signals a concession but does not specify what is being conceded, making the logical chain less precise than needed for this layered argument. "By extension," wrongly implies the following claim is a logical extension of the preceding evidence. "In addition to this evidence," incorrectly frames the counterargument as additional support rather than a reinterpretation that undercuts the evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24QT7JB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively illustrate the claim about Desai''s narrative technique?', E'Literary scholars have noted that novelist Kiran Desai employs a distinctive narrative technique in which descriptions of physical landscapes mirror the emotional states of her characters. Rather than stating characters'' feelings explicitly, Desai allows the external environment to convey internal turmoil or tranquility. Critics argue that this approach creates a layered reading experience, demanding that the audience interpret setting details as psychological commentary rather than mere backdrop.', $lyceon_json$[{"key":"A","text":"\"Desai's prose is notable for its precise historical research, grounding each scene in verifiable details about the political upheavals that shaped mid-twentieth-century India.\""},{"key":"B","text":"\"In Desai's work, a crumbling terrace overtaken by monsoon vines becomes not simply a decaying structure but a register of the protagonist's unraveling sense of belonging.\""},{"key":"C","text":"\"Desai's dialogue captures the rhythms of multilingual households with an authenticity that few contemporary novelists in English have managed to replicate convincingly.\""},{"key":"D","text":"\"What distinguishes Desai from her contemporaries is the sheer density of her symbolism, with every object in her fiction carrying an allegorical meaning traceable to Hindu mythology and its attendant iconographic traditions.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Desai''s technique of using physical landscapes to mirror characters'' emotional states. The quotation about a crumbling terrace serving as a register of the protagonist''s unraveling sense of belonging directly exemplifies this landscape-as-emotion technique. The quotation about historical research addresses factual accuracy in setting, not the psychological mirroring described in the passage. The quotation about dialogue and multilingual households concerns a different element of craft entirely. The quotation about Hindu mythological symbolism describes allegorical density, which differs from the specific technique of landscape reflecting emotional states; it overstates and redirects the claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24RLT7D', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Neuroscientist Priya Chandrasekaran''s 2022 study examined how sleep deprivation affects moral reasoning in 89 adult participants. After 31 hours without sleep, subjects were presented with ethical dilemmas involving trade-offs between individual rights and collective welfare. Sleep-deprived participants did not, as Chandrasekaran had hypothesized, become more utilitarian in their judgments. Instead, they showed increased inconsistency: the same participant would endorse opposing moral frameworks across structurally identical scenarios. Chandrasekaran proposed that fatigue degrades not the content of moral beliefs but the cognitive coherence needed to apply them reliably, a distinction she termed the ''consistency-competence gap.''', $lyceon_json$[{"key":"A","text":"Sleep deprivation causes individuals to abandon their established moral values in favor of utilitarian calculations that maximize collective welfare outcomes."},{"key":"B","text":"Chandrasekaran found that fatigue impairs the consistent application of moral reasoning rather than altering the substance of individuals' moral beliefs."},{"key":"C","text":"The study demonstrated that participants who experienced 31 hours of sleep deprivation developed fundamentally different ethical frameworks compared to their rested baseline assessments."},{"key":"D","text":"Chandrasekaran's research showed that moral reasoning is primarily governed by emotional responses that become unpredictable when cognitive resources are depleted by lack of sleep."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage emphasizes Chandrasekaran''s conclusion that fatigue degrades not the content of moral beliefs but the cognitive coherence needed to apply them reliably. The option about impaired consistent application directly restates this finding. The option about abandoning values for utilitarianism contradicts the passage, which explicitly notes the hypothesis of increased utilitarianism was not confirmed. The option about developing fundamentally different ethical frameworks overstates the findings; participants showed inconsistency in applying frameworks, not a shift to new ones. The option about emotional responses introduces a mechanism the passage never discusses; Chandrasekaran''s explanation centers on cognitive coherence, not emotion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24TZENI', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Based on the text, what can most reasonably be inferred about the amber deposits in the Kaliningrad region?', E'The Kaliningrad region on the Baltic coast contains an estimated 90 percent of the world''s accessible amber reserves. Geologists attribute this concentration to a confluence of factors present roughly 44 million years ago: vast subtropical forests of resin-producing conifers grew atop sedimentary basins that would later be submerged by shallow seas. The resin, buried under marine sediments, polymerized over millennia into amber. Comparable conifer forests existed elsewhere in northern Europe during the same epoch, but their resin deposits were dispersed by glacial activity rather than preserved in stable sedimentary layers.', $lyceon_json$[{"key":"A","text":"The amber found in the Kaliningrad region is chemically distinct from amber deposits discovered in other parts of northern Europe."},{"key":"B","text":"The preservation of amber in the Kaliningrad region depended on geological conditions that protected resin deposits from the dispersal that affected similar deposits elsewhere."},{"key":"C","text":"The conifer forests that produced the resin later found as amber in the Kaliningrad region were significantly larger than comparable forests elsewhere in northern Europe during the same period."},{"key":"D","text":"Geologists expect that further amber reserves of comparable scale will eventually be identified beneath the Baltic Sea floor beyond the Kaliningrad coastal zone."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that comparable forests existed elsewhere but their deposits were dispersed by glacial activity, while the Kaliningrad deposits were preserved in stable sedimentary layers. One can reasonably infer that geological conditions protecting against dispersal were key to preservation. The option about chemical distinctness is not supported; the passage discusses preservation conditions, not chemical composition. The option about forest size misreads the passage, which says comparable forests existed elsewhere, implying similar scale rather than smaller size. The option about future discoveries beneath the Baltic Sea extends well beyond what the passage supports.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25KH3X6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'Glassblower Annika Svedberg has spent nineteen years perfecting a technique that requires her to <u>temper</u> the volatility of molten borosilicate by introducing minute quantities of cerium oxide at precisely calibrated intervals. If the compound is added too early, the glass becomes unworkably brittle; too late, and thermal stress fractures propagate through the cooling matrix. Svedberg describes the process as a negotiation between opposing forces: the material''s natural tendency toward chaos and the artisan''s insistence on structural coherence.', $lyceon_json$[{"key":"A","text":"moderate so as to bring into a balanced state"},{"key":"B","text":"provoke into a state of heightened agitation"},{"key":"C","text":"display openly and without concealment"},{"key":"D","text":"abandon before reaching a conclusive outcome"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that Svedberg manages the volatility of molten glass by adding cerium oxide at precise intervals to prevent brittleness or fracturing, describing the work as a "negotiation between opposing forces." This context indicates that "temper" means to moderate so as to bring into a balanced state. The option about provoking agitation contradicts the passage''s emphasis on controlling and reducing volatility. The option about displaying openly has no semantic connection to the process of managing a chemical reaction. The option about abandoning before conclusion contradicts the passage, which describes Svedberg completing her careful process rather than halting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW261H2W3', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary and wants to acknowledge the significance of Dr. Tanaka''s discovery while also noting a limitation that qualifies its implications. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on Dr. Yuki Tanaka''s deep-sea microbiology research:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A23HR9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the coral reefs near Palau have documented a striking decline in staghorn coral populations over the past eleven years. ______ the elkhorn coral species in the same reef system has demonstrated unexpected resilience, maintaining nearly 93 percent of its original coverage during the same observation period.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"As a result,"},{"key":"C","text":"In other words,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two contrasting observations: staghorn coral has declined while elkhorn coral has remained resilient. "In contrast," correctly signals this opposition between the two findings. "As a result," incorrectly implies a cause-and-effect relationship between the decline and the resilience. "In other words," wrongly suggests the second sentence restates the first. "For this reason," incorrectly treats the decline as the cause of the resilience.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A5Y14N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethnomusicologist Priya Chakrabarti argues that the tonal systems of several West African drumming traditions influenced early Caribbean musical forms. Her 2019 monograph documents parallels between Ewe rhythmic structures and Trinidadian ______ Chakrabarti acknowledges that direct causation is difficult to establish, she maintains that the structural similarities are too numerous and specific to be coincidental.', $lyceon_json$[{"key":"A","text":"calypso, although"},{"key":"B","text":"calypso although"},{"key":"C","text":"calypso. Although"},{"key":"D","text":"calypso, and although"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank must properly separate the clause about the monograph''s documentation from the concessive clause beginning with "although." Starting a new sentence with "Although" correctly introduces a subordinate clause that is followed by the main clause ("she maintains..."), forming a complete and grammatically correct sentence. The option using a comma before "although" creates a comma splice, because the result is two independent clauses (the "although" clause pairs with "she maintains" to form its own full sentence) joined by only a comma. The option with no punctuation before "although" creates a run-on. The option using a comma with "and although" produces a faulty coordination that awkwardly merges the concessive structure into the preceding sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AN8ARV', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation proposed by Nakamura and Chen?', E'Immunologists Yuki Nakamura and Lian Chen observed that patients recovering from severe respiratory infections showed elevated levels of a regulatory T-cell subtype, TR-17, for up to fourteen months after initial symptom onset. Nakamura and Chen proposed that persistent TR-17 elevation suppresses the broader immune response, explaining why these patients exhibit increased vulnerability to secondary infections during the recovery period. Their explanation hinges on TR-17 cells actively dampening the activity of effector immune cells that would otherwise combat new pathogens.', $lyceon_json$[{"key":"A","text":"Patients with elevated TR-17 levels also show increased production of pro-inflammatory cytokines that enhance effector immune cell activity against secondary pathogens during the same recovery period."},{"key":"B","text":"TR-17 cells are found in higher concentrations in lung tissue than in peripheral blood, making standard blood tests an unreliable measure of total TR-17 cell populations throughout the body."},{"key":"C","text":"Secondary infections during the recovery period are most commonly caused by bacterial pathogens rather than the viral agents responsible for the initial respiratory infection."},{"key":"D","text":"Patients who received corticosteroid treatment during their initial respiratory infection showed TR-17 elevation patterns similar to those who did not receive any immunosuppressive therapy during illness."}]$lyceon_json$::jsonb, 'A', NULL, E'Nakamura and Chen''s explanation depends on TR-17 cells dampening effector immune cell activity. A finding that patients with elevated TR-17 also show increased pro-inflammatory cytokines enhancing effector cell activity directly contradicts the proposed suppression mechanism, undermining the explanation. The finding about TR-17 concentration in lung tissue versus blood concerns measurement methodology, not the functional relationship between TR-17 and effector cells. The finding about bacterial versus viral secondary infections identifies pathogen types but does not address whether TR-17 suppresses the immune response. The finding about corticosteroid treatment addresses what causes TR-17 elevation but does not challenge the proposed mechanism by which TR-17 affects immunity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BY21T5', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Conventional accounts of the Harlem Renaissance emphasize its literary and visual arts achievements while treating its musical innovations as a secondary phenomenon. Yet pianist and composer Eubie Blake had already premiered his Broadway score for Shuffle Along in 1921, three years before Alain Locke published The New Negro. Historian Claudette Fournier contends that the timeline alone undermines the standard hierarchy: if the movement''s musical breakthroughs preceded its canonical literary works, then privileging literature over music reflects scholarly habit rather than historical sequence.', $lyceon_json$[{"key":"A","text":"It introduces a commonly held view, presents a historical detail that complicates that view, and then offers an interpretation of the detail's significance"},{"key":"B","text":"It describes two competing artistic movements, evaluates the merits of each, and proposes a compromise that reconciles them"},{"key":"C","text":"It traces the chronological development of a cultural movement from its earliest stages through its eventual decline in public attention"},{"key":"D","text":"It presents a historian's original theory, provides several examples that support the theory, and then acknowledges a significant limitation of the evidence"}]$lyceon_json$::jsonb, 'A', NULL, E'The text first states the conventional view that literary and visual arts are prioritized over music, then introduces the historical fact that Blake''s Broadway score predated Locke''s landmark anthology, and finally presents Fournier''s interpretation that this chronology undermines the standard literary-over-music hierarchy. The option about two competing artistic movements is wrong because the text discusses two art forms within the same movement, not separate movements, and offers no compromise. The option about tracing chronological development is wrong because the text does not narrate the Renaissance''s full arc or decline; it uses one date to challenge a scholarly assumption. The option about presenting a historian''s original theory first is wrong because the text opens with the conventional view, not with Fournier''s argument, and it does not acknowledge a limitation of the evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CDPKQ0', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2019 study published in the journal Ecology Letters, marine biologist Hana Oshiro and her colleagues tracked the migratory patterns of 137 leatherback sea turtles across the eastern Pacific. Using satellite telemetry, the team found that turtles consistently avoided regions where ocean temperatures exceeded 29.4 degrees Celsius, even when those warmer zones contained abundant jellyfish prey. The researchers concluded that thermal tolerance, rather than food availability, is the primary factor governing leatherback migration routes in warming oceans.', $lyceon_json$[{"key":"A","text":"Leatherback sea turtles prefer jellyfish-rich feeding grounds above all other considerations during migration."},{"key":"B","text":"Satellite telemetry has become the standard tool for tracking marine reptile populations across ocean basins."},{"key":"C","text":"Thermal tolerance, not prey abundance, primarily determines the migratory routes of leatherback sea turtles in the eastern Pacific."},{"key":"D","text":"Ocean warming has caused a significant decline in leatherback sea turtle populations throughout the Pacific region over recent decades."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that the researchers concluded thermal tolerance, rather than food availability, is the primary factor governing leatherback migration routes. The option stating thermal tolerance primarily determines migratory routes directly captures this conclusion. The option about jellyfish-rich feeding grounds contradicts the passage, which says turtles avoided warm zones even when jellyfish were abundant. The option about satellite telemetry describes a method used in the study but not its main finding. The option about population decline introduces a claim not supported by the passage, which discusses migration routes rather than population numbers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DXU0BF', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the implications of Petrov''s findings for urban sustainability planning?', E'Urban ecologist Aleksandr Petrov studied nitrogen cycling in 23 mid-sized European cities between 2017 and 2022. His data showed that cities with fragmented green spaces, those divided into parcels smaller than 0.4 hectares, retained only 12 percent of atmospheric nitrogen deposited on vegetated surfaces, while cities with contiguous green corridors exceeding 2.5 hectares retained 47 percent. Petrov attributed the difference to mycorrhizal fungal networks, which transfer nitrogen between plant root systems but require uninterrupted soil connectivity to function. In fragmented landscapes, pavement and compacted substrates sever these networks, forcing each parcel to operate as an isolated nitrogen sink with limited processing capacity. Petrov noted, however, that even the highest-retention cities still exported the majority of deposited nitrogen into waterways.', $lyceon_json$[{"key":"A","text":"Cities seeking to improve nitrogen retention should prioritize connecting existing green spaces into contiguous corridors rather than simply increasing the total area of fragmented green parcels scattered throughout the urban landscape."},{"key":"B","text":"Mycorrhizal fungal networks can be artificially established beneath paved surfaces to restore nitrogen cycling in cities where green space fragmentation is irreversible due to existing infrastructure constraints."},{"key":"C","text":"Urban nitrogen pollution is a negligible environmental concern compared to other forms of urban pollution, given that even well-connected green corridors retain less than half of deposited nitrogen."},{"key":"D","text":"Petrov's findings suggest that mid-sized European cities have fundamentally different nitrogen cycling dynamics than large metropolitan areas, making his results inapplicable to major urban centers worldwide."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage demonstrates that contiguous green corridors retain significantly more nitrogen than fragmented parcels because mycorrhizal networks require uninterrupted soil connectivity. The inference that connectivity matters more than scattered area follows directly from this finding. The option about artificially establishing fungal networks beneath pavement introduces a technological solution the passage never discusses; it goes well beyond what can be inferred. The option dismissing nitrogen pollution as negligible misapplies the detail that even high-retention cities export most nitrogen; the passage frames higher retention as beneficial, not as evidence that the problem is unimportant. The option about inapplicability to large cities introduces a limitation the passage does not suggest; Petrov''s mechanism concerns soil connectivity, not city size.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LBB0PP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Coral bleaching events have intensified across the Indo-Pacific basin since 2014, with satellite thermal imaging revealing that surface water temperatures have exceeded the bleaching threshold in 73 percent of surveyed reef systems. <u>Marine ecologist Danusha Wickramasinghe documented a 41 percent decline in live coral cover at seventeen monitoring stations along the eastern Sri Lankan coastline between 2016 and 2023.</u> Wickramasinghe''s team has since partnered with local fisheries cooperatives to establish shaded nursery platforms designed to cultivate heat-resistant coral genotypes for eventual transplantation onto degraded reef structures.', $lyceon_json$[{"key":"A","text":"It provides a specific research finding that illustrates the broader trend described earlier in the text"},{"key":"B","text":"It challenges the scientific consensus presented at the beginning of the text by introducing contradictory data"},{"key":"C","text":"It shifts the focus of the text from marine biology to the economic effects of coral loss on coastal populations"},{"key":"D","text":"It summarizes the overall argument the text develops across all three of its sentences"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence cites Wickramasinghe''s documentation of a 41 percent decline in live coral cover at specific monitoring stations, which directly supports and illustrates the opening sentence''s claim about intensifying bleaching events. The option about challenging scientific consensus is wrong because the decline data reinforces rather than contradicts the bleaching trend. The option about shifting to economic effects is wrong because the underlined sentence discusses coral cover decline, a biological measurement, not economic consequences. The option about summarizing the overall argument is wrong because the sentence presents one supporting data point rather than encapsulating the full text, which also includes a restoration initiative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MV35WM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Elara Okonkwo has spent over a decade studying the migratory patterns of leatherback sea turtles in the South Atlantic. Her research team, based at the University of Cape Town, tracks individual turtles using satellite-linked ______ this method has revealed that some turtles travel more than eleven thousand kilometers in a single migration cycle.', $lyceon_json$[{"key":"A","text":"transmitters,"},{"key":"B","text":"transmitters, and"},{"key":"C","text":"transmitters and,"},{"key":"D","text":"transmitters, but"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank joins two independent clauses: one about tracking turtles with transmitters and one about what the method revealed. A comma followed by a coordinating conjunction ("and") correctly joins two independent clauses. The option with only a comma after "transmitters" creates a comma splice, which is not grammatically correct. The option placing the comma after "and" rather than before it misplaces the punctuation. The option using "but" introduces an inappropriate contrast, since the second clause does not contradict the first but rather extends it with a result.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NVO43S', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2021 study of pollinator behavior, entomologist Luisa Ferreira observed that carpenter bees visiting jacaranda trees in urban Belo Horizonte displayed foraging strategies markedly different from those of bees in rural areas. Neither the increased ambient noise nor the higher concentration of artificial light ______ to deter the urban carpenter bees from visiting the same clusters of blossoms repeatedly, a pattern Ferreira attributes to the limited availability of alternative nectar sources in dense cityscapes.', $lyceon_json$[{"key":"A","text":"appear"},{"key":"B","text":"are appearing"},{"key":"C","text":"have appeared"},{"key":"D","text":"appears"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject is "Neither the increased ambient noise nor the higher concentration of artificial light." With a "neither...nor" construction, the verb agrees with the nearer subject, which is "the higher concentration" — a singular noun. Therefore the singular "appears" is correct. The plural form "appear" does not agree with the nearer singular subject. The plural progressive "are appearing" also fails singular agreement. The plural perfect "have appeared" likewise does not agree with the singular nearer subject. This question requires recognizing both the neither-nor proximity agreement rule and identifying which noun is closer to the verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NZ2T2L', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "exercised" most nearly mean?', E'In the decades following the collapse of the Achaemenid Empire, the governors of outlying Bactrian provinces <u>exercised</u> considerable autonomy, minting their own coinage, adjudicating land disputes without imperial oversight, and negotiating trade agreements with neighboring Sogdian settlements. Historian Parvaneh Kashani argues that this decentralized authority was not mere rebellion but reflected a deliberate administrative philosophy: central rulers tolerated regional self-governance provided that tribute payments continued uninterrupted.', $lyceon_json$[{"key":"A","text":"employed through deliberate practice and repetition"},{"key":"B","text":"exerted as a form of authority or control"},{"key":"C","text":"physically strengthened through sustained effort"},{"key":"D","text":"eliminated from official administrative procedures"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes governors who minted coinage, adjudicated disputes, and negotiated trade agreements independently, all activities indicating the wielding of power. The meaning of "exercised" that fits this context is exerted as a form of authority or control. The option about deliberate practice and repetition refers to the fitness or training sense of "exercise," which does not apply to political governance. The option about physical strengthening similarly invokes the bodily sense of exercise, which is irrelevant to provincial administration. The option about elimination contradicts the passage entirely, since the governors were actively using their autonomy, not removing it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OA3ZIN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the relationship between melodic complexity and listener engagement?', E'Musicologist Farid Osman analyzed listener engagement data from 2,400 participants who rated 150 instrumental compositions on a continuous attention scale. Compositions with moderate melodic complexity, defined as those containing between 7 and 11 distinct pitch intervals per phrase, received the highest sustained-attention ratings. Pieces with fewer than 7 intervals were rated as monotonous, while those exceeding 11 intervals prompted a sharp decline in attention after the first 90 seconds of listening. Notably, Osman found that the drop-off threshold varied little across participants regardless of their prior musical training, suggesting the effect is not merely a product of listener expertise.', $lyceon_json$[{"key":"A","text":"Listener engagement follows an inverted-U pattern with respect to melodic complexity, peaking at moderate levels and declining when complexity is either too low or too high."},{"key":"B","text":"Musical training enables listeners to sustain attention through highly complex passages that untrained listeners find cognitively overwhelming after brief exposure."},{"key":"C","text":"Compositions with fewer than 7 pitch intervals per phrase are inherently less aesthetically valuable than those falling within the moderate complexity range identified by Osman."},{"key":"D","text":"The sustained-attention ratings collected by Osman primarily reflect listeners' familiarity with specific compositions rather than their responses to structural features of the music itself."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes low engagement at low complexity (monotonous), peak engagement at moderate complexity, and declining engagement at high complexity. This pattern matches an inverted-U relationship. The option about musical training contradicts the passage, which states the drop-off threshold varied little regardless of prior musical training. The option about aesthetic value introduces a judgment the passage does not make; Osman measured attention, not aesthetic worth. The option about familiarity proposes an alternative explanation unsupported by the passage, which attributes the pattern to structural features (pitch intervals per phrase).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OFMIL3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Archaeologist Tomoko Nagashima''s excavation of a seventh-century granary complex in Nara Prefecture yielded 4,200 carbonized rice grains whose isotopic profiles did not match local soil chemistry. Nagashima hypothesized that the grains had been transported from paddies in the Kinai lowlands, over 90 kilometers to the west. <u>Subsequent pollen analysis of sediment layers beneath the granary floor revealed traces of Cryptomeria japonica, a species absent from Nara''s native flora but abundant in Kinai-region forests during the Asuka period.</u> This convergence of isotopic and palynological evidence has led several scholars to revise their understanding of early Japanese tributary networks, suggesting that centralized grain collection operated across a wider geographic radius than previously documented.', $lyceon_json$[{"key":"A","text":"It introduces an independent finding from a separate discipline that corroborates the hypothesis presented in the preceding sentence"},{"key":"B","text":"It qualifies Nagashima's hypothesis by identifying a methodological flaw in the isotopic analysis of the carbonized grains"},{"key":"C","text":"It provides background information about Cryptomeria japonica that contextualizes the archaeological significance of the granary site"},{"key":"D","text":"It restates the central claim of the passage using more precise and technically specialized scientific terminology"}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes pollen analysis (a palynological method) that independently supports Nagashima''s isotope-based hypothesis about grain transport from the Kinai lowlands: the Cryptomeria pollen found at the Nara site is native to Kinai forests, not Nara''s local flora. This introduces corroborating evidence from a different scientific discipline. The option about identifying a methodological flaw is wrong because the pollen evidence strengthens rather than challenges the isotopic findings. The option about providing background on Cryptomeria japonica is wrong because the sentence''s purpose is not to contextualize the species itself but to use its geographic distribution as evidence for the transport hypothesis. The option about restating the central claim in specialized terminology is wrong because the sentence introduces new evidence (pollen data), not a restatement of existing claims.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PB9NJN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about urban wildlife and wants to present a finding that challenges a common assumption about coyote behavior. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes on Dr. Lena Vasquez''s 2022 coyote study:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q6ER6P', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2019 field experiment, agronomist Priya Nandakumar showed that intercropping millet with pigeon pea raised soil nitrogen levels by 37 percent compared to millet monoculture. ______ Nandakumar cautioned that the intercropping method demands precise row spacing: when rows were planted closer than 41 centimeters apart, both crops experienced stunted root development and yields fell below the monoculture baseline.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"To illustrate this point,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence reports a positive finding about intercropping, while the second introduces a significant limitation. "Nevertheless," correctly signals this concession — acknowledging the benefit while pivoting to a caveat. "Furthermore," wrongly implies the second sentence adds to the same positive point. "Specifically," incorrectly suggests the cautionary detail elaborates on the nitrogen finding rather than qualifying it. "To illustrate this point," incorrectly frames the warning as an example supporting the benefit, when it actually undermines it under certain conditions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QPDRAN', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a difference in how the two authors interpret the significance of communal resource management practices?', E'Text 1: Anthropologist Keiko Fujimori studied water-sharing customs among pastoral communities in the Ferghana Valley of Uzbekistan. Fujimori argues that these communities'' elaborate canal-maintenance rituals, which require each household to contribute a fixed number of labor days per season, function primarily as mechanisms of social cohesion. The rituals'' economic inefficiency, she contends, is beside the point: their true value lies in reinforcing kinship obligations and collective identity, making them resistant to replacement by technologically superior irrigation systems.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R2A3AC', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Archaeologist Dmitri Volkov''s excavation of a Bronze Age settlement near the Ural Mountains in 2021 uncovered 43 clay tablets inscribed with symbols previously unknown to scholars. While some researchers initially proposed that the symbols represented a proto-writing system, Volkov''s subsequent analysis of their spatial distribution within the settlement suggested otherwise. The tablets were found exclusively in storage areas associated with grain and livestock, and the symbols corresponded closely to quantities recorded in contemporaneous Mesopotamian trade inventories. Volkov argued that the symbols functioned as a specialized accounting notation rather than a general-purpose writing system, challenging earlier assumptions about literacy development in the region.', $lyceon_json$[{"key":"A","text":"Volkov's analysis suggests that symbols found on clay tablets near the Ural Mountains served as a specialized accounting system rather than a general writing system."},{"key":"B","text":"The discovery of 43 inscribed clay tablets has fundamentally changed how historians understand Bronze Age trade networks between the Ural region and Mesopotamia."},{"key":"C","text":"Scholars have long debated whether Bronze Age settlements in the Ural Mountains region developed writing independently of Mesopotamian influence or derived their systems from external contact."},{"key":"D","text":"Volkov concluded that the storage areas where the tablets were found indicate the settlement's economy depended primarily on grain production rather than livestock management."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Volkov''s argument that the inscribed symbols functioned as accounting notation, not a general-purpose writing system. The option about a specialized accounting system accurately captures this main idea. The option about fundamentally changing understanding of trade networks overstates the passage''s claims; the passage does not discuss broader historiographical shifts. The option about scholarly debate on independent writing development introduces context the passage never mentions. The option about grain versus livestock misreads Volkov''s findings: he noted both grain and livestock storage areas, and his conclusion concerned the symbols'' function, not the settlement''s economic priorities.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R3E3NO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the late nineteenth century, several American universities began offering formal instruction in the natural sciences. At the University of Michigan, geologist Israel Cook Russell ______ a series of expeditions to study glacial formations in Alaska when the university expanded its geology department in 1891, enabling him to secure funding for even more ambitious fieldwork.', $lyceon_json$[{"key":"A","text":"was already conducting"},{"key":"B","text":"has already conducted"},{"key":"C","text":"had already conducted"},{"key":"D","text":"would already conduct"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes an action (conducting expeditions) that was completed before another past event (the university expanding its department in 1891). The past perfect tense "had already conducted" correctly indicates an action completed prior to another past action. The past progressive "was already conducting" would imply the expeditions were ongoing at the time of the expansion rather than already completed. The present perfect "has already conducted" is incorrect because both events are situated in the distant past, not connected to the present. The conditional "would already conduct" incorrectly implies a hypothetical or future-in-the-past sense that does not fit the factual narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SHTMDT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Tomoko Harada uncovered a series of clay tablets in southeastern Turkey that bore inscriptions in an unidentified script. For nearly two decades, linguists struggled to decipher the ______ in 2004, a graduate student named Ravi Subramanian proposed a breakthrough interpretation linking the script to a known Bronze Age trade language.', $lyceon_json$[{"key":"A","text":"script, then,"},{"key":"B","text":"script but"},{"key":"C","text":"script;"},{"key":"D","text":"script, however,"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank separates two independent clauses. A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. The option using a comma with "then" creates a comma splice, since "then" is not a coordinating conjunction and cannot join independent clauses after only a comma. The option using "but" without any preceding punctuation creates a run-on sentence fusing two independent clauses. The option using commas around "however" creates a comma splice, since "however" is a conjunctive adverb and requires a semicolon or period before it when joining independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UV8WR4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Recent neurological studies have demonstrated that the adolescent brain remains remarkably <u>plastic</u> well into the early twenties. Researchers at the Karolinska Institute in Stockholm tracked synaptic density in 137 participants over a nine-year span, finding that environmental stimuli continued to reshape neural pathways far longer than earlier models had predicted. These findings have prompted educators to reconsider the timing of advanced skill instruction, suggesting that intensive training programs may yield stronger results when introduced during this extended window of cortical development.', $lyceon_json$[{"key":"A","text":"artificial or synthetic in composition"},{"key":"B","text":"adaptable and capable of being reshaped"},{"key":"C","text":"rigid and resistant to outside influence"},{"key":"D","text":"visually appealing in outward appearance"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes the adolescent brain as capable of being reshaped by environmental stimuli, with neural pathways continuing to change. The word "plastic" here means adaptable and capable of being reshaped, which aligns with the neuroscience concept of neuroplasticity. The option describing something artificial or synthetic refers to the common everyday meaning of plastic as a material, which is irrelevant in a neurological context. The option describing rigidity directly contradicts the passage''s emphasis on malleability and change. The option about visual appeal has no connection to the scientific discussion of brain development.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UYPGKO', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how does the finding described in Text 2 relate to the argument presented in Text 1?', E'Text 1: Literary critic Henning Bjornstad maintains that the spare, unadorned prose style of mid-twentieth-century Scandinavian novelists was a deliberate aesthetic response to the region''s Protestant cultural inheritance. According to Bjornstad, writers such as Hjalmar Soderberg and Tarjei Vesaas rejected ornamental language because they associated rhetorical excess with moral dishonesty, a conviction rooted in Lutheran suspicions of performative display.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VJW8OP', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Economist Rajan Muthuraman argues that microfinance institutions in rural Tamil Nadu have fundamentally transformed household economic behavior. His 2019 survey of 820 borrowers in Thanjavur district found that 67 percent reported increased savings rates within eighteen months of receiving their first microloan, a pattern Muthuraman attributes to the financial discipline imposed by structured repayment schedules.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WM9FPQ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Botanists at the University of Cape Town have hypothesized that the unusually high species diversity of fynbos shrublands in South Africa''s Western Cape results primarily from the region''s mosaic of distinct soil types. According to this hypothesis, sharp boundaries between nutrient-poor sandstone soils and clay-rich granite soils create ecological barriers that promote speciation by isolating plant populations within small, geochemically distinct patches.', $lyceon_json$[{"key":"A","text":"Fynbos species transplanted to uniform clay soils in greenhouse conditions show growth rates comparable to those observed in wild sandstone habitats."},{"key":"B","text":"Genetic analysis reveals that closely related fynbos species on adjacent but geochemically different soil patches diverged more recently than species on the same soil type separated by greater distances."},{"key":"C","text":"Satellite imagery shows that fynbos shrublands have expanded their total range by approximately 7 percent over the past four decades despite rising average temperatures in the Western Cape."},{"key":"D","text":"Pollination studies indicate that most fynbos species rely on wind rather than insects for reproduction, reducing the likelihood of cross-pollination between neighboring plant populations."}]$lyceon_json$::jsonb, 'B', NULL, E'The hypothesis claims that soil-type boundaries promote speciation by isolating populations in distinct geochemical patches. A finding that closely related species on adjacent but different soil types diverged more recently than species on the same soil type at greater distances directly supports isolation by soil boundaries as a speciation driver. The option about greenhouse growth rates addresses tolerance, not speciation driven by soil boundaries. The option about range expansion concerns overall habitat extent, which is unrelated to the mechanism of soil-boundary-driven speciation. The option about wind pollination describes a reproductive mechanism that could reduce gene flow but does not specifically connect speciation to soil-type boundaries as the hypothesis requires.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
